-- SOLO PRUEBAS LOCALES · V6 · funciones SQL reales de N-V5-03 y de la prioridad de alarmas (después de extra_v5: usa su alarma v5_id y su aviso v5_nid)
create temp table v6_checks(name text, ok boolean, detail text);
\set A  'e0000000-0000-0000-0000-00000000000a'
\set W  'c0000000-0000-0000-0000-0000000000a1'
create or replace function pg_temp.v6ok(nid uuid) returns text language sql as $f$ select public.push_recipient_allowed(nid)->>'ok' || ':' || coalesce(public.push_recipient_allowed(nid)->>'motivo', '') $f$;
create temp table v6_r as select pg_temp.v6ok((select nid from v5_nid)) base;
select pg_temp.v5sync(true); update public.profiles set disabled_modules = array['COMERCIAL'] where id = :'W'; select pg_temp.v5sync(false);
update v6_r set base = base || ' | restringido=' || pg_temp.v6ok((select nid from v5_nid));
select pg_temp.v5sync(true); update public.profiles set disabled_modules = '{}', role = 'OPERARIO_DEPOSITO' where id = :'W'; select pg_temp.v5sync(false);
delete from public.user_permission_overrides where user_id = :'W' and permission_code = 'com.approve';
update v6_r set base = base || ' | rol=' || pg_temp.v6ok((select nid from v5_nid));
select pg_temp.v5sync(true); update public.profiles set role = 'SOLO_LECTURA', status = 'DESHABILITADO' where id = :'W'; select pg_temp.v5sync(false);
insert into public.user_permission_overrides(user_id, permission_code, granted, set_by, reason) values (:'W', 'com.approve', true, :'A', 'restaurado por la prueba V6');
update v6_r set base = base || ' | deshabilitado=' || pg_temp.v6ok((select nid from v5_nid));
select pg_temp.v5sync(true); update public.profiles set status = 'ACTIVO' where id = :'W'; select pg_temp.v5sync(false);
update v6_r set base = base || ' | restaurado=' || pg_temp.v6ok((select nid from v5_nid));
insert into v6_checks select 'V6-R01 (N-V5-03) push_recipient_allowed: el aviso de alarma ya ENCOLADO solo se envía si el destinatario CONSERVA el acceso al enviar: COMERCIAL restringido, cambio de ROL y DESHABILITADO → no; al restablecer → sí',
  base = 'true: | restringido=false:DESTINATARIO_SIN_ACCESO_ACTUAL | rol=false:DESTINATARIO_SIN_ACCESO_ACTUAL | deshabilitado=false:DESTINATARIO_SIN_ACCESO_ACTUAL | restaurado=true:', base from v6_r;
insert into v6_checks select 'V6-R02 (N-V5-03) cada omisión queda AUDITADA (COM_ALARM_PUSH_OMITIDO con destinatario, alarma y motivo) y el historial de la alarma NO se borra',
  (select count(*) >= 3 from public.audit_log where action = 'COM_ALARM_PUSH_OMITIDO' and target_id = (select nid from v5_nid)::text)
  and exists (select 1 from public.audit_log where action = 'COM_ALARM_PUSH_OMITIDO' and after->>'motivo' = 'DESTINATARIO_NO_ACTIVO')
  and exists (select 1 from public.com_alarm_events where notification_id = (select nid from v5_nid)),
  (select count(*)::text from public.audit_log where action = 'COM_ALARM_PUSH_OMITIDO') from (select 1) z;
insert into public.notifications(user_id, type, title, body) values (:'W', 'REQUEST_CREATED', 'otro tipo', 'v6');
insert into v6_checks select 'V6-R03 avisos de OTROS tipos: sin restricción comercial (comportamiento previo intacto)',
  public.push_recipient_allowed((select id from public.notifications where body = 'v6' limit 1))->>'motivo' = 'TIPO_SIN_RESTRICCION', '' from (select 1) z;
-- prioridad: la cola tiene un trabajo GENERAL más viejo y uno de ALARMA más nuevo
update public.push_jobs set status = 'SENT' where status in ('QUEUED', 'ERROR', 'SENDING');
insert into public.notifications(user_id, type, title, body, created_at) values (:'W', 'REQUEST_CREATED', 'viejo', 'v6-general', now() - interval '1 hour');
insert into public.notifications(user_id, type, title, body) values (:'W', 'COM_ALARMA', 'urgente', 'v6-alarma');
update public.push_jobs set created_at = now() - interval '1 hour' where notification_id = (select id from public.notifications where body = 'v6-general');
create temp table v6_c as select (select array_agg(n.body) from public.claim_com_alarm_push_jobs(10) j join public.notifications n on n.id = j.notification_id) alarmas;
alter table v6_c add column general text[]; update v6_c set general = (select array_agg(n.body) from public.claim_push_jobs(10) j join public.notifications n on n.id = j.notification_id);
insert into v6_checks select 'V6-C01 PRIORIDAD: claim_com_alarm_push_jobs toma SOLO avisos de alarma (aunque haya trabajos más viejos) y la cola general toma el resto, sin superponerse',
  alarmas = array['v6-alarma'] and general = array['v6-general'], array_to_string(alarmas, ',') || ' | ' || array_to_string(general, ',') from v6_c;
insert into v6_checks select 'V6-C02 las funciones nuevas de push son SOLO de servicio (ni anon ni usuarios autenticados)',
  not has_function_privilege('authenticated', 'public.push_recipient_allowed(uuid)', 'EXECUTE') and not has_function_privilege('anon', 'public.push_recipient_allowed(uuid)', 'EXECUTE')
  and not has_function_privilege('authenticated', 'public.claim_com_alarm_push_jobs(integer)', 'EXECUTE') and not has_function_privilege('anon', 'public.claim_com_alarm_push_jobs(integer)', 'EXECUTE'), '' from (select 1) z;

-- revisión anticipatoria: TODA función definida por las migraciones del módulo (con cualquier prefijo) queda fuera del alcance de anon
insert into v6_checks select 'V6-P01 (revisión anticipatoria) NINGUNA función definida por el módulo (com_, _com_, push_*, claim_com_*, auxiliares de instalación) es ejecutable por anon (salvo funciones de DISPARADOR, que no se pueden invocar directamente: ver V6-P02)',
  not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('_com_active', '_com_admin', '_com_alarm_escalation', '_com_alarm_initial', '_com_alarm_notify', '_com_alarm_role', '_com_alarm_view', '_com_ar_day', '_com_billing_docs', '_com_can_see_full', '_com_can_upload_source', '_com_event', '_com_install_configure', '_com_install_log_inmutable', '_com_install_ready', '_com_kpi_raw', '_com_kpi_sources', '_com_label', '_com_link_source', '_com_module_open', '_com_month_covered', '_com_month_sales', '_com_norm', '_com_notify', '_com_recompute_reviews', '_com_require_session', '_com_terms', '_com_view', 'claim_com_alarm_push_jobs', 'com_alarm_attend', 'com_alarm_by_notification', 'com_alarm_escalate_due', 'com_alarm_history', 'com_alarm_history_page', 'com_alarm_push_status', 'com_alarm_raise', 'com_alarm_settings', 'com_approvers', 'com_client_finance', 'com_config', 'com_create_request', 'com_decide', 'com_dispatch_stats', 'com_history', 'com_import_clients', 'com_ingest', 'com_ingest_error', 'com_kpi_billing', 'com_kpi_billing_detail', 'com_kpi_for_client', 'com_list', 'com_my_alarms', 'com_my_alarms_page', 'com_my_notifications', 'com_my_push_devices', 'com_order_alerts', 'com_register_source_file', 'com_report', 'com_request_detail', 'com_respond', 'com_search_clients', 'com_set_alarm_settings', 'com_set_assignment', 'com_set_cc_verificacion', 'com_set_comp_type', 'com_set_kpi_mode', 'com_set_routing', 'com_set_saldo_rule', 'com_set_settings', 'com_sources_status', 'com_track', 'push_recipient_allowed', 'push_session_valid', 'queue_notification_push', 'trg_com_alarm_events_immutable', 'trg_com_doc_part', 'trg_com_events_immutable', 'trg_com_source_immutable') and has_function_privilege('anon', p.oid, 'EXECUTE') and p.prorettype <> 'trigger'::regtype),
  coalesce((select string_agg(p.oid::regprocedure::text, ', ') from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('_com_active', '_com_admin', '_com_alarm_escalation', '_com_alarm_initial', '_com_alarm_notify', '_com_alarm_role', '_com_alarm_view', '_com_ar_day', '_com_billing_docs', '_com_can_see_full', '_com_can_upload_source', '_com_event', '_com_install_configure', '_com_install_log_inmutable', '_com_install_ready', '_com_kpi_raw', '_com_kpi_sources', '_com_label', '_com_link_source', '_com_module_open', '_com_month_covered', '_com_month_sales', '_com_norm', '_com_notify', '_com_recompute_reviews', '_com_require_session', '_com_terms', '_com_view', 'claim_com_alarm_push_jobs', 'com_alarm_attend', 'com_alarm_by_notification', 'com_alarm_escalate_due', 'com_alarm_history', 'com_alarm_history_page', 'com_alarm_push_status', 'com_alarm_raise', 'com_alarm_settings', 'com_approvers', 'com_client_finance', 'com_config', 'com_create_request', 'com_decide', 'com_dispatch_stats', 'com_history', 'com_import_clients', 'com_ingest', 'com_ingest_error', 'com_kpi_billing', 'com_kpi_billing_detail', 'com_kpi_for_client', 'com_list', 'com_my_alarms', 'com_my_alarms_page', 'com_my_notifications', 'com_my_push_devices', 'com_order_alerts', 'com_register_source_file', 'com_report', 'com_request_detail', 'com_respond', 'com_search_clients', 'com_set_alarm_settings', 'com_set_assignment', 'com_set_cc_verificacion', 'com_set_comp_type', 'com_set_kpi_mode', 'com_set_routing', 'com_set_saldo_rule', 'com_set_settings', 'com_sources_status', 'com_track', 'push_recipient_allowed', 'push_session_valid', 'queue_notification_push', 'trg_com_alarm_events_immutable', 'trg_com_doc_part', 'trg_com_events_immutable', 'trg_com_source_immutable') and has_function_privilege('anon', p.oid, 'EXECUTE') and p.prorettype <> 'trigger'::regtype), 'ninguna') from (select 1) z;
create or replace function pg_temp.v6trg() returns text language plpgsql as $f$ begin set local role anon; perform public.queue_notification_push(); reset role; return 'INVOCADA'; exception when others then reset role; return sqlerrm; end $f$;
insert into v6_checks select 'V6-P02 queue_notification_push (función de DISPARADOR de la base publicada, permisos previos sin cambios) NO se puede invocar directamente: no es un camino de acceso',
  pg_temp.v6trg() ~ 'trigger', pg_temp.v6trg() from (select 1) z;
